/// <summary>
/// Parameters of a database refresh job started from the menu or in batch.
/// </summary>
[DataContractAttribute,
 SysOperationContractProcessingAttribute(classStr(BDRJobUIBuilder))]
public final class BDRJobContract
{
    private BDREnvironmentId environmentId;
    private RefRecId continueJobRecId;
}

Method.Source:
/// <summary>
/// The environment configured for the current instance.
/// </summary>
[DataMemberAttribute('EnvironmentId'),
 SysOperationLabelAttribute(literalStr("@BDR:Environment")),
 SysOperationHelpTextAttribute(literalStr("@BDR:RunCurrentEnvironmentHelp"))]
public BDREnvironmentId parmEnvironmentId(BDREnvironmentId _environmentId = environmentId)
{
    environmentId = _environmentId;
    return environmentId;
}

/// <summary>
/// Set when a batch job continues the tasks a service call scheduled.
/// </summary>
[DataMemberAttribute('ContinueJobRecId'),
 SysOperationControlVisibilityAttribute(false)]
public RefRecId parmContinueJobRecId(RefRecId _continueJobRecId = continueJobRecId)
{
    continueJobRecId = _continueJobRecId;
    return continueJobRecId;
}
